# BentoML: package and serve a trained model
import bentoml
from bentoml.io import NumpyNdarray

# Save model to BentoML store
bento_model = bentoml.sklearn.save_model("fraud_classifier", model)

# Define a serving endpoint
svc = bentoml.Service("fraud_service", runners=[bento_model.to_runner()])

@svc.api(input=NumpyNdarray(), output=NumpyNdarray())
def predict(input_data):
    return bento_model.to_runner().predict.run(input_data)
